-- Create list_categories table
CREATE TABLE list_categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    list_id UUID NOT NULL REFERENCES lists(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    sort_index INTEGER NOT NULL DEFAULT 0,
    icon TEXT,
    color TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),

    -- Unique constraint to avoid duplicate names per list (or allow if you prefer)
    CONSTRAINT unique_list_category_name UNIQUE (list_id, name)
);

-- Enable RLS
ALTER TABLE list_categories ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for list_categories
-- Users can only access categories for lists they own
CREATE POLICY "Users can view their own list categories" ON list_categories
    FOR SELECT USING (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can insert categories for their own lists" ON list_categories
    FOR INSERT WITH CHECK (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can update their own list categories" ON list_categories
    FOR UPDATE USING (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can delete their own list categories" ON list_categories
    FOR DELETE USING (
        list_id IN (
            SELECT id FROM lists WHERE user_id = auth.uid()
        )
    );

-- Create index for performance
CREATE INDEX idx_list_categories_list_id ON list_categories(list_id);
CREATE INDEX idx_list_categories_sort_index ON list_categories(list_id, sort_index);

-- Create updated_at trigger
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ language 'plpgsql';

CREATE TRIGGER update_list_categories_updated_at 
    BEFORE UPDATE ON list_categories 
    FOR EACH ROW 
    EXECUTE FUNCTION update_updated_at_column();

