-- Create listed_gear_item table (junction table for gear items in lists with metadata)
CREATE TABLE listed_gear_item (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    gear_id UUID NOT NULL REFERENCES gear_items(id) ON DELETE RESTRICT,
    list_category_id UUID REFERENCES list_categories(id) ON DELETE SET NULL,
    quantity INTEGER NOT NULL DEFAULT 1,
    worn BOOLEAN NOT NULL DEFAULT false,
    weight_g_override INTEGER, -- nullable, allows override of gear item weight
    notes TEXT, -- nullable
    sort_index INTEGER, -- nullable, for custom ordering within category
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE listed_gear_item ENABLE ROW LEVEL SECURITY;

-- Create RLS policies for listed_gear_item
-- Users can only access listed gear items for gear they own
CREATE POLICY "Users can view their own listed gear items" ON listed_gear_item
    FOR SELECT USING (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can insert listed gear items for their own gear" ON listed_gear_item
    FOR INSERT WITH CHECK (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
        AND (
            list_category_id IS NULL OR
            list_category_id IN (
                SELECT lc.id FROM list_categories lc
                JOIN lists l ON l.id = lc.list_id
                WHERE l.user_id = auth.uid()
            )
        )
    );

CREATE POLICY "Users can update their own listed gear items" ON listed_gear_item
    FOR UPDATE USING (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "Users can delete their own listed gear items" ON listed_gear_item
    FOR DELETE USING (
        gear_id IN (
            SELECT id FROM gear_items WHERE user_id = auth.uid()
        )
    );

-- Create indexes for performance
CREATE INDEX idx_listed_gear_item_gear_id ON listed_gear_item(gear_id);
CREATE INDEX idx_listed_gear_item_category_id ON listed_gear_item(list_category_id);
CREATE INDEX idx_listed_gear_item_category_sort ON listed_gear_item(list_category_id, sort_index);

-- Create updated_at trigger
CREATE TRIGGER update_listed_gear_item_updated_at 
    BEFORE UPDATE ON listed_gear_item 
    FOR EACH ROW 
    EXECUTE FUNCTION update_updated_at_column();

