import { memo, useMemo } from 'react'
import { Card, CardContent, CardFooter } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Edit2, Trash2, Package, Weight, Hash, ImageOff } from 'lucide-react'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearCardProps {
  item: GearItem
  weightUnit?: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
}

export const GearCard = memo(function GearCard({ item, weightUnit = 'g', onEdit, onDelete }: GearCardProps) {
  const totalWeight = useMemo(() => item.weight_g * (item.quantity ?? 1), [item.weight_g, item.quantity])

  return (
    <Card className="hover:shadow-md transition-all duration-150 hover:scale-[1.01] border-border/40 h-full flex flex-col relative active:scale-[0.99]">
      {/* Category Badge - always in top-right corner */}
      <Badge variant="outline" className="absolute top-4 right-4 z-10 bg-background/90 backdrop-blur-sm">
        {item.item_type}
      </Badge>

      {/* Image Section - always show on desktop for alignment, conditional on mobile */}
      <div className={`relative h-32 sm:h-48 bg-muted overflow-hidden flex items-center justify-center ${
        !item.image_url ? 'hidden md:flex' : ''
      }`}>
        {item.image_url ? (
          <img
            src={item.image_url}
            alt={item.label}
            className="w-full h-full object-cover"
            onError={(e) => {
              // Show placeholder on error instead of hiding
              const img = e.currentTarget
              img.style.display = 'none'
              const placeholder = img.nextElementSibling as HTMLElement
              if (placeholder) {
                placeholder.style.display = 'flex'
              }
            }}
          />
        ) : null}
        {/* Placeholder - shown when no image or on error */}
        <div className={`${item.image_url ? 'hidden' : ''} absolute inset-0 flex items-center justify-center`}>
          <ImageOff className="h-12 w-12 text-muted-foreground/30" />
        </div>
      </div>

      <CardContent className="p-6 flex-1 flex flex-col">
        <div className="space-y-4 flex-1">
          {/* Header with consistent height */}
          <div className="min-h-[4rem]">
            <h3 className="text-base font-medium text-muted-foreground">
              {item.url ? (
                <a
                  href={item.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-primary hover:underline"
                >
                  {item.label}
                </a>
              ) : (
                item.label
              )}
            </h3>
            <p className="text-lg font-semibold line-clamp-1 mt-1">
              {item.model || item.description || item.brand || 'No model specified'}
            </p>
            {item.brand && (item.model || item.description) && (
              <p className="text-sm text-muted-foreground mt-0.5">
                {item.brand}
              </p>
            )}
          </div>

          {/* Stats Grid */}
          <div className="grid grid-cols-3 gap-4 py-4 border-y border-border/40">
            <div className="text-center">
              <div className="flex items-center justify-center mb-1 text-muted-foreground">
                <Weight className="h-3 w-3 mr-1" />
                <span className="text-xs">Weight</span>
              </div>
              <p className="text-sm font-medium">{formatWeightWithUnit(item.weight_g, weightUnit)}</p>
            </div>
            <div className="text-center">
              <div className="flex items-center justify-center mb-1 text-muted-foreground">
                <Hash className="h-3 w-3 mr-1" />
                <span className="text-xs">Qty</span>
              </div>
              <p className="text-sm font-medium">{item.quantity ?? 1}</p>
            </div>
            <div className="text-center">
              <div className="flex items-center justify-center mb-1 text-muted-foreground">
                <Package className="h-3 w-3 mr-1" />
                <span className="text-xs">Total</span>
              </div>
              <p className="text-sm font-medium">{formatWeightWithUnit(totalWeight, weightUnit)}</p>
            </div>
          </div>


          {/* Properties */}
          {(item.worn || item.consumable) && (
            <div className="flex gap-2">
              {item.worn && (
                <Badge variant="secondary" className="text-xs">
                  Worn
                </Badge>
              )}
              {item.consumable && (
                <Badge variant="secondary" className="text-xs">
                  Consumable
                </Badge>
              )}
            </div>
          )}

          {/* Notes */}
          {item.notes && (
            <p className="text-sm text-muted-foreground line-clamp-2">
              {item.notes}
            </p>
          )}

          {/* Price */}
          {item.price && (
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">Price</span>
              <span className="font-medium">${item.price.toFixed(2)}</span>
            </div>
          )}
        </div>
      </CardContent>
      <CardFooter className="p-4 pt-0 flex gap-2 mt-auto">
        <Button
          variant="outline"
          size="sm"
          className="flex-1"
          onClick={() => onEdit(item)}
        >
          <Edit2 className="h-3 w-3 mr-1" />
          Edit
        </Button>
        <Button
          variant="outline"
          size="sm"
          className="flex-1 text-destructive hover:text-destructive"
          onClick={() => onDelete(item)}
        >
          <Trash2 className="h-3 w-3 mr-1" />
          Delete
        </Button>
      </CardFooter>
    </Card>
  )
})

import { CollectionCompactRow, type CompactRowAction } from '@/components/shared/CollectionCompactRow'
import { Edit2, Trash2, Copy } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearCompactRowProps {
  item: GearItem
  weightUnit: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  onDuplicate?: (item: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'>) => void
  onClick?: (item: GearItem) => void
}

export function GearCompactRow({ 
  item, 
  weightUnit, 
  onEdit, 
  onDelete,
  onDuplicate,
  onClick 
}: GearCompactRowProps) {
  // Build subtitle from brand, model, and description (matches the screenshot format)
  const subtitle = [item.brand, item.model, item.description]
    .filter(Boolean)
    .join(', ')

  // Category badge
  const categoryBadge = (
    <Badge variant="outline" className="text-xs px-2 py-0">
      {item.item_type}
    </Badge>
  )

  // Properties badges (compact version)
  const properties = (
    <div className="flex gap-1">
      {item.worn && (
        <span className="text-xs text-muted-foreground">Worn</span>
      )}
      {item.consumable && (
        <span className="text-xs text-muted-foreground">Consumable</span>
      )}
    </div>
  )

  // Data columns for compact view: Category, Weight, Qty, Total, Properties
  const totalWeight = item.weight_g * (item.quantity ?? 1)
  const columns = [
    categoryBadge, // Category
    formatWeightWithUnit(item.weight_g, weightUnit), // Weight
    item.quantity ?? 1, // Qty  
    formatWeightWithUnit(totalWeight, weightUnit), // Total
    properties // Properties (Worn/Consumable)
  ]

  // Build actions
  const actions: CompactRowAction[] = [
    {
      label: 'Edit',
      icon: <Edit2 className="mr-2 h-4 w-4" />,
      onClick: () => onEdit(item)
    },
    ...(onDuplicate ? [{
      label: 'Duplicate',
      icon: <Copy className="mr-2 h-4 w-4" />,
      onClick: () => {
        const { id, created_at, updated_at, user_id, ...cloneData } = item
        const newItem = { ...cloneData, label: `${cloneData.label} (Copy)` }
        onDuplicate(newItem)
      }
    }] : []),
    {
      label: 'Delete',
      icon: <Trash2 className="mr-2 h-4 w-4" />,
      onClick: () => onDelete(item),
      variant: 'destructive' as const
    }
  ]

  return (
    <CollectionCompactRow
      title={item.label}
      subtitle={subtitle}
      columns={columns}
      actions={actions}
      onClick={onClick ? () => onClick(item) : undefined}
      url={item.url || undefined}
    />
  )
}

import { CollectionRow, type RowAction, type RowBadge } from '@/components/shared/CollectionRow'
import { Edit2, Trash2, Copy } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface GearRowProps {
  item: GearItem
  weightUnit: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  onDuplicate?: (item: Omit<GearItem, 'id' | 'created_at' | 'updated_at' | 'user_id'>) => void
  onClick?: (item: GearItem) => void
  showProperties?: boolean // Whether to show the Properties column
}

export function GearRow({ 
  item, 
  weightUnit, 
  onEdit, 
  onDelete,
  onDuplicate,
  onClick,
  showProperties = true
}: GearRowProps) {
  // Build subtitle from model/description
  const subtitle = [item.model, item.description]
    .filter(Boolean)
    .join(' • ')

  // Category badge
  const category: RowBadge = { 
    label: item.item_type, 
    variant: 'outline' 
  }

  // Build metadata for mobile
  const weightDisplay = formatWeightWithUnit(item.weight_g, weightUnit)
  const metadata = (item.quantity ?? 1) > 1 
    ? `${weightDisplay} each • ${item.quantity ?? 1} items`
    : weightDisplay

  // Build secondary info for desktop columns (Weight, Qty, Total, Properties?)
  const totalWeight = item.weight_g * (item.quantity ?? 1)
  const baseSecondaryInfo = [
    formatWeightWithUnit(item.weight_g, weightUnit),
    item.quantity ?? 1,
    formatWeightWithUnit(totalWeight, weightUnit)
  ]

  const propertiesColumn = (
    <div className="flex items-center gap-1">
      {item.worn && (
        <Badge variant="secondary" className="text-xs">
          Worn
        </Badge>
      )}
      {item.consumable && (
        <Badge variant="secondary" className="text-xs">
          Consumable
        </Badge>
      )}
    </div>
  )

  const secondaryInfo = showProperties 
    ? [...baseSecondaryInfo, propertiesColumn]
    : baseSecondaryInfo

  const columnClasses = showProperties 
    ? ['text-right', 'text-right', 'text-right font-medium', '']
    : ['text-right', 'text-right', 'text-right font-medium']

  // Build actions
  const actions: RowAction[] = [
    {
      label: 'Edit',
      icon: <Edit2 className="h-4 w-4" />,
      onClick: () => onEdit(item)
    },
    ...(onDuplicate ? [{
      label: 'Duplicate',
      icon: <Copy className="h-4 w-4" />,
      onClick: () => {
        const { id, created_at, updated_at, user_id, ...cloneData } = item
        const newItem = { ...cloneData, label: `${cloneData.label} (Copy)` }
        onDuplicate(newItem)
      }
    }] : []),
    {
      label: 'Delete',
      icon: <Trash2 className="h-4 w-4" />,
      onClick: () => onDelete(item),
      variant: 'destructive',
      separator: true
    }
  ]

  return (
    <CollectionRow
      title={item.label}
      subtitle={subtitle}
      brand={item.brand}
      category={category}
      metadata={metadata}
      secondaryInfo={secondaryInfo}
      columnClasses={columnClasses}
      actions={actions}
      onClick={onClick ? () => onClick(item) : undefined}
      url={item.url || undefined}
    />
  )
}

import { memo, useMemo } from 'react'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { 
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Edit2, Trash2, MoreHorizontal, Copy, ChevronUp, ChevronDown, ChevronsUpDown, FileText } from 'lucide-react'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'
import type { ViewMode } from '@/pages/GearPage'

export type SortField = 'name' | 'category' | 'weight_grams' | 'quantity' | 'total'
export type SortDirection = 'asc' | 'desc'

interface GearTableProps {
  items: GearItem[]
  viewMode: ViewMode
  weightUnit?: WeightUnit
  onEdit: (item: GearItem) => void
  onDelete: (item: GearItem) => void
  showActions?: boolean
  // Legacy sorting props (now optional and can be omitted)
  sortField?: SortField
  sortDirection?: SortDirection
  onSort?: (field: SortField) => void
}

export const GearTable = memo(function GearTable({ 
  items, 
  viewMode, 
  weightUnit = 'g',
  onEdit, 
  onDelete, 
  showActions = true,
  sortField,
  sortDirection,
  onSort 
}: GearTableProps) {
  const isCompact = viewMode === 'compact'

  // Memoize summary calculations
  const { totalWeight, totalQuantity, totalCombinedWeight } = useMemo(() => ({
    totalWeight: items.reduce((sum, item) => sum + item.weight_grams, 0),
    totalQuantity: items.reduce((sum, item) => sum + item.quantity, 0),
    totalCombinedWeight: items.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)
  }), [items])

  const getSortIcon = (field: SortField) => {
    if (sortField !== field) {
      return <ChevronsUpDown className="ml-1 h-3 w-3 text-muted-foreground/50" />
    }
    return sortDirection === 'asc' 
      ? <ChevronUp className="ml-1 h-3 w-3" />
      : <ChevronDown className="ml-1 h-3 w-3" />
  }

  return (
    <div className="bg-white rounded-lg border border-border/40 overflow-hidden">
      <Table>
        <TableHeader>
          <TableRow className={isCompact ? 'h-8' : 'h-10'}>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium cursor-pointer hover:bg-accent/50`}
              onClick={() => onSort?.('name')}
            >
              <div className="flex items-center">
                Item
                {getSortIcon('name')}
              </div>
            </TableHead>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium cursor-pointer hover:bg-accent/50 hidden sm:table-cell`}
              onClick={() => onSort?.('category')}
            >
              <div className="flex items-center">
                Category
                {getSortIcon('category')}
              </div>
            </TableHead>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium text-right cursor-pointer hover:bg-accent/50 hidden sm:table-cell`}
              onClick={() => onSort?.('weight_grams')}
            >
              <div className="flex items-center justify-end">
                Weight
                {getSortIcon('weight_grams')}
              </div>
            </TableHead>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium text-right cursor-pointer hover:bg-accent/50 hidden sm:table-cell`}
              onClick={() => onSort?.('quantity')}
            >
              <div className="flex items-center justify-end">
                Qty
                {getSortIcon('quantity')}
              </div>
            </TableHead>
            <TableHead 
              className={`${isCompact ? 'text-xs' : 'text-sm'} font-medium text-right cursor-pointer hover:bg-accent/50 hidden md:table-cell`}
              onClick={() => onSort?.('total')}
            >
              <div className="flex items-center justify-end">
                Total
                {getSortIcon('total')}
              </div>
            </TableHead>
            {!isCompact && (
              <TableHead className="text-sm font-medium hidden sm:table-cell">
                Properties
              </TableHead>
            )}
            {showActions && (
              <TableHead className="text-right">
                <span className="sr-only">Actions</span>
              </TableHead>
            )}
          </TableRow>
        </TableHeader>
        <TableBody>
          {items.map((item) => (
            <TableRow 
              key={item.id} 
              className={`hover:bg-accent/50 transition-colors ${
                isCompact ? 'h-10' : 'h-14'
              }`}
            >
              <TableCell className={isCompact ? 'py-1' : 'py-2'}>
                <div className={isCompact ? 'space-y-0' : 'space-y-1'}>
                  <div className={`${isCompact ? 'text-sm' : 'text-base'}`}>
                    {item.url ? (
                      <a
                        href={item.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-primary hover:underline"
                      >
                        {item.name}
                      </a>
                    ) : (
                      item.name
                    )}
                  </div>
                  {(item.model || item.description) && (
                    <div className={`text-muted-foreground ${isCompact ? 'text-xs' : 'text-sm'}`}>
                      {item.model || item.description}
                    </div>
                  )}
                  {!isCompact && item.brand && (
                    <div className="text-xs text-muted-foreground">
                      {item.brand}
                    </div>
                  )}
                  {/* Mobile-only: Show category, weight, and properties inline */}
                  <div className="sm:hidden text-xs text-muted-foreground mt-1">
                    {item.category} • {formatWeightWithUnit(item.weight_grams, weightUnit)}
                    {item.worn && <span> • Worn</span>}
                    {item.consumable && <span> • Consumable</span>}
                  </div>
                </div>
              </TableCell>
              <TableCell className={`${isCompact ? 'py-1' : 'py-2'} hidden sm:table-cell`}>
                <Badge variant="outline" className={isCompact ? 'text-xs py-0' : ''}>
                  {item.category}
                </Badge>
              </TableCell>
