    const compactColumns = [
      {
        key: 'name',
        label: 'Item',
        sortable: true,
        sortValue: (item: GearItem) => item.name
      },
      {
        key: 'category',
        label: 'Category',
        sortable: true,
        hideOnMobile: true,
        className: 'text-right',
        sortValue: (item: GearItem) => item.category
      },
      {
        key: 'weight_grams',
        label: 'Weight',
        sortable: true,
        hideOnMobile: true,
        className: 'text-right',
        sortValue: (item: GearItem) => item.weight_grams
      },
      {
        key: 'quantity',
        label: 'Qty',
        sortable: true,
        hideOnMobile: true,
        className: 'text-right',
        sortValue: (item: GearItem) => item.quantity
      },
      {
        key: 'total',
        label: 'Total',
        sortable: true,
