import { describe, it, expect, vi, beforeEach } from 'vitest'
import { createGearRepository } from './gearRepository'
import { supabase } from './supabase'
import type { GearItem } from '@/types/database'

vi.mock('./supabase', () => ({
  supabase: {
    from: vi.fn()
  }
}))

describe('GearRepository', () => {
  const mockUserId = 'test-user-123'
  const mockGearItem: GearItem = {
    id: 'gear-123',
    user_id: mockUserId,
    name: 'Test Backpack',
    weight_grams: 1000,
    category: 'Backpack',
    quantity: 1,
    worn: false,
    consumable: false,
    brand: 'Test Brand',
    notes: null,
    price: null,
    description: null,
    image_url: null,
    created_at: '2024-01-01T00:00:00Z',
    updated_at: '2024-01-01T00:00:00Z'
  }

  beforeEach(() => {
    vi.clearAllMocks()
  })

  describe('create', () => {
    it('should create a single gear item', async () => {
      const mockInsert = vi.fn().mockReturnThis()
      const mockSelect = vi.fn().mockReturnThis()
      const mockSingle = vi.fn().mockResolvedValue({ data: mockGearItem, error: null })

      vi.mocked(supabase.from).mockReturnValue({
        insert: mockInsert,
        select: mockSelect,
        single: mockSingle
      } as any)

      const repo = createGearRepository(mockUserId)
      const { id, user_id, created_at, updated_at, ...itemToCreate } = mockGearItem
      const result = await repo.create(itemToCreate)

      expect(supabase.from).toHaveBeenCalledWith('gear_items')
      expect(mockInsert).toHaveBeenCalledWith({ ...itemToCreate, user_id: mockUserId })
      expect(mockSelect).toHaveBeenCalled()
      expect(mockSingle).toHaveBeenCalled()
      expect(result).toEqual(mockGearItem)
    })

    it('should throw error when creation fails', async () => {
      const mockError = new Error('Database error')
      vi.mocked(supabase.from).mockReturnValue({
        insert: vi.fn().mockReturnThis(),
        select: vi.fn().mockReturnThis(),
        single: vi.fn().mockResolvedValue({ data: null, error: mockError })
      } as any)

      const repo = createGearRepository(mockUserId)
      const { id, user_id, created_at, updated_at, ...itemToCreate } = mockGearItem

      await expect(repo.create(itemToCreate)).rejects.toThrow('Database error')
    })
  })

  describe('createMany', () => {
    it('should create multiple gear items', async () => {
      const mockItems = [mockGearItem, { ...mockGearItem, id: 'gear-456', name: 'Test Tent' }]
      const mockInsert = vi.fn().mockReturnThis()
      const mockSelect = vi.fn().mockResolvedValue({ data: mockItems, error: null })

      vi.mocked(supabase.from).mockReturnValue({
        insert: mockInsert,
        select: mockSelect
      } as any)

      const repo = createGearRepository(mockUserId)
      const itemsToCreate = mockItems.map(({ id, user_id, created_at, updated_at, ...item }) => item)
      const result = await repo.createMany(itemsToCreate)

      expect(supabase.from).toHaveBeenCalledWith('gear_items')
      expect(mockInsert).toHaveBeenCalledWith(
        itemsToCreate.map(item => ({ ...item, user_id: mockUserId }))
      )
      expect(mockSelect).toHaveBeenCalled()
      expect(result).toEqual(mockItems)
    })
  })

  describe('read', () => {
    it('should read a gear item by id', async () => {
      const mockSelect = vi.fn().mockReturnThis()
      const mockEq = vi.fn().mockReturnThis()
      const mockSingle = vi.fn().mockResolvedValue({ data: mockGearItem, error: null })

      vi.mocked(supabase.from).mockReturnValue({
        select: mockSelect,
        eq: mockEq,
        single: mockSingle
      } as any)

      const repo = createGearRepository(mockUserId)
      const result = await repo.read('gear-123')

      expect(supabase.from).toHaveBeenCalledWith('gear_items')
      expect(mockSelect).toHaveBeenCalledWith('*')
      expect(mockEq).toHaveBeenCalledWith('id', 'gear-123')
      expect(mockEq).toHaveBeenCalledWith('user_id', mockUserId)
      expect(result).toEqual(mockGearItem)
    })

    it('should return null when item not found', async () => {
      vi.mocked(supabase.from).mockReturnValue({
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        single: vi.fn().mockResolvedValue({ data: null, error: { code: 'PGRST116' } })
      } as any)

      const repo = createGearRepository(mockUserId)
      const result = await repo.read('nonexistent')

      expect(result).toBeNull()
    })
  })

  describe('update', () => {
    it('should update a gear item', async () => {
      const updates = { name: 'Updated Backpack', weight_grams: 900 }
      const updatedItem = { ...mockGearItem, ...updates }

      const mockUpdate = vi.fn().mockReturnThis()
      const mockEq = vi.fn().mockReturnThis()
      const mockSelect = vi.fn().mockReturnThis()
      const mockSingle = vi.fn().mockResolvedValue({ data: updatedItem, error: null })

      vi.mocked(supabase.from).mockReturnValue({
        update: mockUpdate,
        eq: mockEq,
        select: mockSelect,
        single: mockSingle
      } as any)

      const repo = createGearRepository(mockUserId)
      const result = await repo.update('gear-123', updates)

      expect(supabase.from).toHaveBeenCalledWith('gear_items')
      expect(mockUpdate).toHaveBeenCalledWith(updates)
      expect(mockEq).toHaveBeenCalledWith('id', 'gear-123')
      expect(mockEq).toHaveBeenCalledWith('user_id', mockUserId)
      expect(result).toEqual(updatedItem)
    })
  })

  describe('delete', () => {
    it('should delete a gear item', async () => {
      const mockDelete = vi.fn().mockReturnThis()
      const mockEq = vi.fn()
      mockEq.mockReturnValueOnce({ eq: vi.fn().mockResolvedValue({ error: null }) })

      vi.mocked(supabase.from).mockReturnValue({
        delete: mockDelete,
        eq: mockEq
      } as any)

      const repo = createGearRepository(mockUserId)
      await repo.delete('gear-123')

      expect(supabase.from).toHaveBeenCalledWith('gear_items')
      expect(mockDelete).toHaveBeenCalled()
      expect(mockEq).toHaveBeenCalledWith('id', 'gear-123')
    })
  })

  describe('list', () => {
    it('should list all gear items for a user', async () => {
      const mockItems = [mockGearItem, { ...mockGearItem, id: 'gear-456' }]
      const mockSelect = vi.fn().mockReturnThis()
      const mockEq = vi.fn().mockReturnThis()
      const mockOrder = vi.fn().mockReturnThis()
