import { describe, it, expect } from 'vitest'
import { parseCsv, validateGearItems, checkForDuplicates } from './csvParser'

describe('CSV Parser', () => {
  describe('parseCsv', () => {
    it('should parse basic CSV with required fields', () => {
      const csv = `name,weight,category
Tent,1200g,Shelter
Sleeping Bag,800g,Sleep System`

      const result = parseCsv(csv)

      // Debug output
      if (!result.success) {
        console.log('Parse result:', result)
      }

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2)
      expect(result.errors).toHaveLength(0)

      expect(result.data[0]).toMatchObject({
        label: 'Tent',
        weight_g: 1200,
        item_type: 'Shelter',
        worn: false,
        consumable: false
      })
    })

    it('should handle different weight units', () => {
      const csv = `name,weight
Item1,2.5oz
Item2,1200g
Item3,1.5 oz`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].weight_grams).toBeCloseTo(71, 0) // 2.5oz ≈ 71g
      expect(result.data[1].weight_grams).toBe(1200)
      expect(result.data[2].weight_grams).toBeCloseTo(43, 0) // 1.5oz ≈ 43g
    })

    it('should handle quoted fields with commas', () => {
      const csv = `name,weight,description
"Tent, 2-person",1200g,"Lightweight, waterproof"
Stove,150g,"Compact, efficient"`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].name).toBe('Tent, 2-person')
      expect(result.data[0].description).toBe('Lightweight, waterproof')
    })

    it('should handle flexible column naming', () => {
      const csv = `Item Name,Weight (g),Gear Type,Qty,Brand
Ultralight Tent,1000,Shelter,1,Zpacks
Water Bottle,100,Water,2,Nalgene`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2)
      expect(result.data[0]).toMatchObject({
        name: 'Ultralight Tent',
        weight_grams: 1000,
        category: 'Shelter',
        quantity: 1,
        brand: 'Zpacks'
      })
    })

    it('should handle boolean fields', () => {
      const csv = `name,weight,worn,consumable
Base Layer,200g,true,false
Energy Bar,50g,no,yes`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].worn).toBe(true)
      expect(result.data[0].consumable).toBe(false)
      expect(result.data[1].worn).toBe(false)
      expect(result.data[1].consumable).toBe(true)
    })

    it('should handle price parsing', () => {
      const csv = `name,weight,price
Tent,1200g,$299.99
Stove,150g,89.50`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].price).toBe(299.99)
      expect(result.data[1].price).toBe(89.50)
    })

    it('should fail with missing required columns', () => {
      const csv = `description,color
Nice tent,Blue`

      const result = parseCsv(csv)

      expect(result.success).toBe(false)
      expect(result.errors).toContain('No name/item column found. Required columns: name, weight')
    })

    it('should handle empty rows and malformed data gracefully', () => {
      const csv = `name,weight,category
Tent,1200g,Shelter

,invalid,
Good Item,500g,Other`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(2) // Should skip empty/invalid rows
      expect(result.data[0].name).toBe('Tent')
      expect(result.data[1].name).toBe('Good Item')
    })

    it('should provide detailed error messages for invalid rows', () => {
      const csv = `name,weight
,200g
ValidItem,invalid_weight`

      const result = parseCsv(csv)

      expect(result.errors.length).toBeGreaterThan(0)
      expect(result.errors.some(e => e.includes('Item name is required'))).toBe(true)
    })

    it('should intelligently detect when description is used for categories', () => {
      const csv = `name,weight,description
Tent,1200g,shelter
Sleeping Bag,800g,sleep
Stove,200g,cook`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data).toHaveLength(3)
      expect(result.data[0].category).toBe('shelter')
      expect(result.data[1].category).toBe('sleep')
      expect(result.data[2].category).toBe('cook')
    })

    it('should extract brand information from descriptions', () => {
      const csv = `name,weight,description
Ultralight Tent,1000g,zpacks duplex ultralight
Water Filter,50g,sawyer mini portable
Headlamp,80g,petzl actik rechargeable`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].brand).toBe('Zpacks')
      expect(result.data[1].brand).toBe('Sawyer')
      expect(result.data[2].brand).toBe('Petzl')
    })

    it('should handle mixed usage patterns intelligently', () => {
      const csv = `name,weight,description,notes
Base Layer,200g,patagonia merino,warm and comfortable
Sleeping Pad,400g,sleep,r-value 4.5
Cook Pot,150g,cooking gear,titanium construction`

      const result = parseCsv(csv)

      expect(result.success).toBe(true)
      expect(result.data[0].brand).toBe('Patagonia')
      expect(result.data[0].notes).toBe('warm and comfortable')
      expect(result.data[1].category).toBe('Sleep System') // Intelligent detection converts 'sleep' to proper category
      expect(result.data[1].notes).toBe('r-value 4.5')
      expect(result.data[2].category).toBe('Cooking') // Intelligent detection converts 'cooking gear' to proper category
      expect(result.data[2].notes).toBe('titanium construction')
    })
  })

  describe('validateGearItems', () => {
    it('should validate correct items', () => {
      const items = [
        {
          name: 'Tent',
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Water Bottle',
          weight_grams: 150,
          category: 'Water',
          quantity: 2,
          worn: false,
          consumable: false,
          price: 25.99
        }
      ]

      const result = validateGearItems(items)

      expect(result.valid).toHaveLength(2)
      expect(result.invalid).toHaveLength(0)
    })

    it('should catch validation errors', () => {
      const items = [
        {
          name: 'A', // Too short
          weight_grams: 0, // Invalid weight
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Heavy Item',
          weight_grams: 100000, // Too heavy
          category: 'Other',
          quantity: 0, // Invalid quantity
          worn: false,
          consumable: false,
          price: -10 // Negative price
        }
      ]

      const result = validateGearItems(items)

      expect(result.valid).toHaveLength(0)
      expect(result.invalid).toHaveLength(2)

      // Check specific validation errors
      const firstItemErrors = result.invalid[0].errors
      expect(firstItemErrors).toContain('Name must be at least 2 characters')
      expect(firstItemErrors).toContain('Weight must be greater than 0')

      const secondItemErrors = result.invalid[1].errors
      expect(secondItemErrors).toContain('Weight seems unusually high (>50kg)')
      expect(secondItemErrors).toContain('Quantity must be at least 1')
      expect(secondItemErrors).toContain('Price cannot be negative')
    })

    it('should handle edge cases', () => {
      const items = [
        {
          name: 'Valid Item',
          weight_grams: 100,
          category: 'Other',
          quantity: 1,
          worn: false,
          consumable: false,
          price: 0 // Zero price should be valid
        }
      ]

      const result = validateGearItems(items)

      expect(result.valid).toHaveLength(1)
      expect(result.invalid).toHaveLength(0)
    })
  })

  describe('checkForDuplicates', () => {
    it('should identify exact duplicates', () => {
      const items = [
        {
          name: 'Tent',
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Tent', // Exact duplicate
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Sleeping Bag',
          weight_grams: 800,
          category: 'Sleep',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2)
      expect(result.duplicates).toHaveLength(1)
      expect(result.warnings).toContain('Found 1 potential duplicate (similar name/weight/brand)')
      expect(result.duplicates[0].duplicateOf).toBe(0) // Duplicate of first item
    })

    it('should identify duplicates with similar weights', () => {
      const items = [
        {
          name: 'Water Bottle',
          weight_grams: 150,
          category: 'Water',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Water Bottle', // Similar weight (within 5g tolerance)
          weight_grams: 153,
          category: 'Water',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should not consider items with different weights as duplicates', () => {
      const items = [
        {
          name: 'Water Bottle',
          weight_grams: 150,
          category: 'Water',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Water Bottle', // Different weight (>5g difference)
          weight_grams: 200,
          category: 'Water',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2)
      expect(result.duplicates).toHaveLength(0)
    })

    it('should consider case-insensitive name matching', () => {
      const items = [
        {
          name: 'Tent',
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'TENT', // Same name, different case
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should handle brand matching for duplicates', () => {
      const items = [
        {
          name: 'Tent',
          brand: 'Zpacks',
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Tent',
          brand: 'MSR', // Different brand
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Tent',
          brand: 'Zpacks', // Same brand - should be duplicate
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(2) // Zpacks and MSR tents
      expect(result.duplicates).toHaveLength(1) // Second Zpacks tent
    })

    it('should handle items without brands', () => {
      const items = [
        {
          name: 'Water Bottle',
          weight_grams: 150,
          category: 'Water',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Water Bottle', // No brand on either - should be duplicate
          weight_grams: 150,
          category: 'Water',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(1)
    })

    it('should handle multiple duplicates correctly', () => {
      const items = [
        {
          name: 'Energy Bar',
          weight_grams: 50,
          category: 'Food',
          quantity: 1,
          worn: false,
          consumable: true
        },
        {
          name: 'Energy Bar',
          weight_grams: 50,
          category: 'Food',
          quantity: 1,
          worn: false,
          consumable: true
        },
        {
          name: 'Energy Bar',
          weight_grams: 50,
          category: 'Food',
          quantity: 1,
          worn: false,
          consumable: true
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(1)
      expect(result.duplicates).toHaveLength(2)
      expect(result.warnings).toContain('Found 2 potential duplicates (similar name/weight/brand)')
    })

    it('should return no duplicates for unique items', () => {
      const items = [
        {
          name: 'Tent',
          weight_grams: 1200,
          category: 'Shelter',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Sleeping Bag',
          weight_grams: 800,
          category: 'Sleep',
          quantity: 1,
          worn: false,
          consumable: false
        },
        {
          name: 'Stove',
          weight_grams: 200,
          category: 'Cook',
          quantity: 1,
          worn: false,
          consumable: false
        }
      ]

      const result = checkForDuplicates(items)

      expect(result.unique).toHaveLength(3)
      expect(result.duplicates).toHaveLength(0)
      expect(result.warnings).toHaveLength(0)
    })
  })
})

